"use client";
/* Cactus, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Cactus(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("cactus"); }, []);
  return React.createElement("piix-sprite", { "name": "cactus", ...piixAttrs(props) });
}

export default Cactus;
